-- Reference copy of installed estate authority. This does not author trust rules.
-- No subjects, claims, evidence or dispositions are created by this migration.
SET NOCOUNT ON;
SET XACT_ABORT ON;
IF DB_NAME()<>N'sfx-identity' THROW 51000,'IDENTITY_DATABASE_MISMATCH',1;
IF @@TRANCOUNT<>0 THROW 51000,'IDENTITY_MIGRATION_REQUIRES_NO_OUTER_TRANSACTION',1;
BEGIN TRANSACTION;
BEGIN TRY
IF SCHEMA_ID(N'ledger') IS NULL EXEC(N'CREATE SCHEMA [ledger] AUTHORIZATION dbo;');
IF OBJECT_ID(N'ledger.authority_ref',N'U') IS NULL
CREATE TABLE ledger.authority_ref(
 definition_digest binary(32) NOT NULL CONSTRAINT PK_ledger_authority_ref PRIMARY KEY,
 semantic_address nvarchar(512) COLLATE Latin1_General_100_BIN2 NOT NULL,
 authority_kind varchar(32) NOT NULL,
 content varbinary(max) NOT NULL,
 retained_at datetimeoffset(7) NOT NULL,
 CONSTRAINT CK_ledger_authority_content CHECK(HASHBYTES('SHA2_256',content)=definition_digest AND DATALENGTH(content)>0),
 CONSTRAINT CK_ledger_authority_kind CHECK(authority_kind IN('policy','evaluator')));
IF OBJECT_ID(N'ledger.trust_state',N'U') IS NULL
CREATE TABLE ledger.trust_state(
 policy_digest binary(32) NOT NULL REFERENCES ledger.authority_ref(definition_digest),
 state_id int NOT NULL,state_name varchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
 CONSTRAINT PK_ledger_trust_state PRIMARY KEY(policy_digest,state_id),
 CONSTRAINT UQ_ledger_trust_state_name UNIQUE(policy_digest,state_name));
IF OBJECT_ID(N'ledger.evidence_class',N'U') IS NULL
CREATE TABLE ledger.evidence_class(
 policy_digest binary(32) NOT NULL REFERENCES ledger.authority_ref(definition_digest),
 class_name varchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
 CONSTRAINT PK_ledger_evidence_class PRIMARY KEY(policy_digest,class_name));
IF OBJECT_ID(N'ledger.claim_kind',N'U') IS NULL
CREATE TABLE ledger.claim_kind(
 policy_digest binary(32) NOT NULL REFERENCES ledger.authority_ref(definition_digest),
 kind_id varchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
 kind_json nvarchar(max) NOT NULL CHECK(ISJSON(kind_json)=1),
 CONSTRAINT PK_ledger_claim_kind PRIMARY KEY(policy_digest,kind_id));
IF OBJECT_ID(N'ledger.evaluation_rule',N'U') IS NULL
CREATE TABLE ledger.evaluation_rule(
 policy_digest binary(32) NOT NULL,
 rule_id varchar(128) COLLATE Latin1_General_100_BIN2 NOT NULL,
 claim_kind varchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
 scope nvarchar(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
 target_state varchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
 available bit NOT NULL,rule_digest binary(32) NOT NULL,
 rule_json nvarchar(max) NOT NULL CHECK(ISJSON(rule_json)=1),
 CONSTRAINT PK_ledger_rule PRIMARY KEY(policy_digest,rule_id),
 CONSTRAINT FK_ledger_rule_claim FOREIGN KEY(policy_digest,claim_kind) REFERENCES ledger.claim_kind(policy_digest,kind_id),
 CONSTRAINT FK_ledger_rule_state FOREIGN KEY(policy_digest,target_state) REFERENCES ledger.trust_state(policy_digest,state_name));
IF NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'ledger.evaluation_rule') AND name=N'CK_ledger_rule_reference')
ALTER TABLE ledger.evaluation_rule WITH CHECK ADD CONSTRAINT CK_ledger_rule_reference CHECK(
 rule_id=JSON_VALUE(rule_json,'$.id') COLLATE Latin1_General_100_BIN2 AND JSON_VALUE(rule_json,'$.id') IS NOT NULL
 AND claim_kind=JSON_VALUE(rule_json,'$.claimKind') COLLATE Latin1_General_100_BIN2 AND JSON_VALUE(rule_json,'$.claimKind') IS NOT NULL
 AND scope=JSON_VALUE(rule_json,'$.scope') COLLATE Latin1_General_100_BIN2 AND JSON_VALUE(rule_json,'$.scope') IS NOT NULL
 AND target_state=JSON_VALUE(rule_json,'$.target') COLLATE Latin1_General_100_BIN2 AND JSON_VALUE(rule_json,'$.target') IS NOT NULL
 AND available=CASE WHEN JSON_VALUE(rule_json,'$.available')='false' THEN 0 ELSE 1 END
 AND rule_digest=HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(varchar(max),rule_json COLLATE Latin1_General_100_BIN2_UTF8))));
DECLARE @policy nvarchar(max)=N'{"address":{"id":"run-evidence-trust-policy.v1","kind":"AUTHORITY","namespace":"sidefx:authorities"},"format":"sidefx-semantic-definition.v1","semantics":{"policyVersion":"run-evidence-trust-policy.v1","revision":1,"scope":"A disposition applies to one claim and one explicit scope. State ids are vocabulary, never scores.","states":[{"id":0,"name":"UNTRUSTED"},{"id":1,"name":"IDENTIFIED"},{"id":2,"name":"DECLARED"},{"id":3,"name":"AUTHORITY_BOUND"},{"id":4,"name":"OBSERVED"},{"id":5,"name":"CONFORMANT"},{"id":6,"name":"CROSS_VERIFIED"},{"id":7,"name":"FORMALLY_VERIFIED"},{"id":8,"name":"ADMITTED"}],"evidenceClasses":["identity","declaration","authority","observation","conformance","cross-verification","formal-proof","admission"],"polarities":["SUPPORTS","REFUTES","NOT_OBSERVABLE"],"verificationOutcomes":["SATISFIED","VIOLATED","NOT_OBSERVABLE","INCONCLUSIVE"],"proofOutcomes":["PROVEN","REFUTED","UNKNOWN","TIMEOUT"],"limitationKinds":["NOT_VERIFIED","ASSUMPTION","OUT_OF_SCOPE","NOT_OBSERVABLE"],"claimKinds":[{"id":"C1","name":"run-outcome","subjectKind":"run","scope":"returned-outcome","statementFields":["runId","capabilityId","namespaceId","capabilityDefinitionDigest","graphDigest","executorDigest","outcomeVariant"]},{"id":"C2","name":"provider-exchange","subjectKind":"provider-invocation","scope":"exchange-observation","statementFields":["runId","providerId","providerDefinitionDigest","ownerCellExecutionId","providerCellExecutionId","status","durationMilliseconds"]}],"identity":{"algorithm":"sha256","manifest":"Retain the exact immutable UTF-8 JSON bytes with their declared format and canonicalization version; verify the digest over those bytes. Do not substitute local selection for attributable execution identity.","requiredRunFields":["runId","capabilityId","namespaceId","capabilityDefinitionDigest","graphDigest","executorDigest","executorProvenance","manifestVersion","canonicalizationVersion"],"changedDigest":"new-subject-with-lineage"},"rules":[{"id":"C1.returned-outcome.observed.v1","claimKind":"C1","scope":"returned-outcome","target":"OBSERVED","evaluation":"declared-evidence-prerequisites.v1","requiredEvidenceClasses":["identity","declaration","authority","observation"],"requiredChecks":["subject-manifest-digest-matches","statement-matches-manifest","executor-attributable-to-run","authority-selected-and-digest-matched","observation-producer-identified","terminal-receipt-matches-statement","trace-ranges-complete","retained-content-digests-match","input-manifest-complete","evaluator-identified-and-authorized"],"contradiction":"Any retained REFUTES link in this claim and scope holds reliance; later SUPPORTS never erases it.","missing":"NOT_OBSERVABLE with named missing references; never counts as support.","limitations":[{"kind":"NOT_VERIFIED","statement":"Returned outcome does not establish business correctness, conformance or independent verification."},{"kind":"OUT_OF_SCOPE","statement":"No formal proof or governance admission is established."}],"unavailableChecks":"Return NOT_OBSERVABLE. Never assume a required check passed."},{"id":"C2.exchange.observed.v1","claimKind":"C2","scope":"exchange-observation","target":"OBSERVED","available":false,"reason":"Exact operation/provider ownership and retained exchange content require SDA S1-S3; no containment inference establishes ownership."}],"unavailableStates":["IDENTIFIED","DECLARED","AUTHORITY_BOUND","CONFORMANT","CROSS_VERIFIED","FORMALLY_VERIFIED","ADMITTED"],"higherStatePolicy":"Vocabulary is declared; no disposition rule for these targets is admitted by this revision. A missing rule is unavailable.","independence":"Different producer names or repeated runs alone do not qualify. CROSS_VERIFIED stays unavailable pending a materially independent, lineage-qualified rule.","governance":"ADMITTED is writable only through separate authorized governance admission; a capability outcome with that spelling is not ledger admission.","invalidation":{"triggers":["subject-digest-changed","authority-revoked","rule-changed","relevant-refutation","assumption-unmet"],"history":"Append invalidation or supersession and retain the old basis. Unaffected claim scopes remain independent."},"replay":{"mode":"Re-evaluate retained evidence; never re-execute providers.","required":["subject-manifest","statement","scope","authority-bytes-and-digests","evidence-bytes-and-digests","producer-identities","rule-bytes-and-digest","evaluator-identity","input-manifest","limitations"],"missingOrPurged":"NOT_OBSERVABLE with missing references; a retained digest alone does not establish replay.","proof":"Retain exact obligation, scope, explicit assumptions, prover/checker identities and certificate; unavailable until a declared proof rule exists."}}}';
DECLARE @evaluator nvarchar(max)=N'{"document":"sidefx-capability-authority.v1","capabilityId":"evaluate-run-evidence-claim","meaning":{"intent":"Evaluate a claim-scoped run evidence basis against pinned estate rules","outcome":"The caller receives deterministic checks, missing references and contradictions; no ledger rows are written"},"cli":{"display":{"select":"outcome","as":"json"}},"contracts":[{"id":"run-evidence-claim-evaluation-request.v1","schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","additionalProperties":false,"required":["contractId","payload"],"properties":{"contractId":{"const":"run-evidence-claim-evaluation-request.v1"},"payload":{"type":"object"}}}},{"id":"run-evidence-claim-evaluation.v1","schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","additionalProperties":true,"required":["contractId","outcome","checks","limitations"],"properties":{"contractId":{"const":"run-evidence-claim-evaluation.v1"},"outcome":{"enum":["SATISFIED","VIOLATED","NOT_OBSERVABLE","INCONCLUSIVE"]},"checks":{"type":"array"},"limitations":{"type":"array"}}}}],"scenarios":[{"scenarioId":"evaluate-run-evidence-claim","name":"Evaluate retained claim evidence","inputId":"run-evidence-claim-evaluation-request","inputContract":"run-evidence-claim-evaluation-request.v1","eventId":"run-evidence-claim-evaluation-requested","eventAuthority":"evaluate-run-evidence-claim.v1","outcomeId":"run-evidence-claim-evaluation","outcomeContract":"run-evidence-claim-evaluation.v1","terminal":true,"root":true,"given":"an authenticated ledger snapshot with exact retained identities and evidence","when":"the declared evaluator compares bytes and checks the pinned rule prerequisites","then":"the reading reports a scoped evaluation and every missing or contradictory basis without writing a disposition","operations":[{"operationId":"evaluate-run-evidence-claim.0","kind":"invoke-port","portId":"evaluate-run-evidence-claim-port"}],"portBindings":[{"portId":"evaluate-run-evidence-claim-port","platformCapabilityId":"sda-embodiment-plan-port.v1","configuration":{"statement":"-- Pure evaluation of an authenticated ledger snapshot. This statement never\n-- writes a claim or authenticates a submitter. Only the private ledger service\n-- may persist its result after deriving producer\/caller bindings from storage.\nDECLARE @p nvarchar(max)=JSON_QUERY(@input,''$.payload'');\nIF ISJSON(@p)<>1 OR DATALENGTH(@p)>16777216 THROW 51000,''TRUST_INPUT_INVALID'',1;\nDECLARE @claim nvarchar(max)=JSON_QUERY(@p,''$.claim''),\n @subject nvarchar(max)=JSON_QUERY(@p,''$.subject''),\n @claimText nvarchar(max),@manifest nvarchar(max),@policy nvarchar(max),@policyBytes nvarchar(max),\n @policyDigest varchar(71)=JSON_VALUE(@p,''$.policyDigest''),\n @rule nvarchar(max),@ruleDigest varchar(71),@evaluatorDigest varchar(71),@evaluatorBytes nvarchar(max);\nSELECT @claimText=content FROM OPENJSON(@claim) WITH(content nvarchar(max) ''$.statement'');\nSELECT @manifest=content FROM OPENJSON(@subject) WITH(content nvarchar(max) ''$.manifest'');\nIF ISNULL(ISJSON(@manifest),0)<>1 SET @manifest=N''{}'';\nIF ISNULL(ISJSON(@claimText),0)<>1 SET @claimText=N''{}'';\n\nSELECT TOP(1) @policyBytes=CONVERT(nvarchar(max),CONVERT(varchar(max),co.content_bytes) COLLATE Latin1_General_100_BIN2_UTF8)\nFROM model.semantic_object so JOIN model.identity_namespace n ON n.namespace_pk=so.namespace_pk\nJOIN model.semantic_object_definition d ON d.semantic_object_pk=so.semantic_object_pk\nJOIN model.estate_definition ed ON ed.semantic_object_definition_pk=d.semantic_object_definition_pk AND ed.estate_model_pk=@estate_model_pk\nJOIN source.content_object co ON co.content_object_pk=d.canonical_content_pk\nWHERE n.namespace_id=N''sidefx:authorities'' AND so.object_kind=N''AUTHORITY'' AND so.declared_id=N''run-evidence-trust-policy.v1''\n AND N''sha256:''+LOWER(CONVERT(varchar(64),d.definition_digest,2))=@policyDigest COLLATE Latin1_General_100_BIN2\nORDER BY d.semantic_object_definition_pk DESC;\nSET @policy=COALESCE(JSON_QUERY(@policyBytes,''$.semantics''),N''{}'');\nSELECT @rule=value FROM OPENJSON(@policy,''$.rules'') WHERE JSON_VALUE(value,''$.id'')=JSON_VALUE(@p,''$.ruleId'') COLLATE Latin1_General_100_BIN2;\nSET @ruleDigest=N''sha256:''+LOWER(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),CONVERT(varchar(max),@rule COLLATE Latin1_General_100_BIN2_UTF8))),2));\nSELECT TOP(1) @evaluatorDigest=N''sha256:''+JSON_VALUE(CONVERT(nvarchar(max),CONVERT(varchar(max),co.content_bytes) COLLATE Latin1_General_100_BIN2_UTF8),''$.semantics.document_digest'')\nFROM model.semantic_object so JOIN model.identity_namespace n ON n.namespace_pk=so.namespace_pk\nJOIN model.semantic_object_definition d ON d.semantic_object_pk=so.semantic_object_pk\nJOIN model.estate_definition ed ON ed.semantic_object_definition_pk=d.semantic_object_definition_pk AND ed.estate_model_pk=@estate_model_pk\nJOIN source.content_object co ON co.content_object_pk=d.canonical_content_pk\nWHERE n.namespace_id=N''sidefx:capability-documents'' AND so.object_kind=N''CAPABILITY_DOCUMENT'' AND so.declared_id=N''evaluate-run-evidence-claim''\nORDER BY d.semantic_object_definition_pk DESC;\nSELECT @evaluatorBytes=CONVERT(nvarchar(max),CONVERT(varchar(max),content_bytes) COLLATE Latin1_General_100_BIN2_UTF8)\nFROM source.content_object WHERE content_digest=TRY_CONVERT(binary(32),SUBSTRING(@evaluatorDigest,8,64),2);\n\nDECLARE @checks TABLE(id varchar(100) PRIMARY KEY,outcome varchar(20) NOT NULL,reason nvarchar(512) NOT NULL);\nDECLARE @invalidShape bit=CASE WHEN EXISTS(SELECT 1 FROM OPENJSON(@p,''$.evidence'') e\n WHERE e.type<>5 OR ISNULL(DATALENGTH(JSON_VALUE(e.value,''$.id'')),0) NOT BETWEEN 2 AND 600\n OR ISNULL(DATALENGTH(JSON_VALUE(e.value,''$.role'')),0) NOT BETWEEN 2 AND 128\n OR ISNULL(DATALENGTH(JSON_VALUE(e.value,''$.class'')),0) NOT BETWEEN 2 AND 128\n OR ISNULL(DATALENGTH(JSON_VALUE(e.value,''$.polarity'')),0) NOT BETWEEN 2 AND 64\n OR ISNULL(DATALENGTH(JSON_VALUE(e.value,''$.scope'')),0) NOT BETWEEN 2 AND 200\n OR ISNULL(DATALENGTH(JSON_VALUE(e.value,''$.subjectDigest'')),0)<>142\n OR ISNULL(DATALENGTH(JSON_VALUE(e.value,''$.producerDigest'')),0)<>142\n OR ISNULL(DATALENGTH(JSON_VALUE(e.value,''$.digest'')),0)<>142) THEN 1 ELSE 0 END;\nDECLARE @parts TABLE(id nvarchar(300) COLLATE Latin1_General_100_BIN2,role varchar(64) COLLATE Latin1_General_100_BIN2,class varchar(64) COLLATE Latin1_General_100_BIN2,polarity varchar(32) COLLATE Latin1_General_100_BIN2,\n subjectDigest varchar(71) COLLATE Latin1_General_100_BIN2,scope nvarchar(100) COLLATE Latin1_General_100_BIN2,producerDigest varchar(71) COLLATE Latin1_General_100_BIN2,digest varchar(71) COLLATE Latin1_General_100_BIN2,content nvarchar(max),valid bit);\nINSERT @parts\nSELECT id,role,class,polarity,subjectDigest,scope,producerDigest,digest,content,\n CASE WHEN content IS NOT NULL AND ISJSON(content)=1 AND DATALENGTH(digest)=71\n AND digest=N''sha256:''+LOWER(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),CONVERT(varchar(max),content COLLATE Latin1_General_100_BIN2_UTF8))),2)) COLLATE Latin1_General_100_BIN2 THEN 1 ELSE 0 END\nFROM OPENJSON(@p,''$.evidence'') WITH(id nvarchar(300),role varchar(64) COLLATE Latin1_General_100_BIN2,class varchar(64) COLLATE Latin1_General_100_BIN2,polarity varchar(32) COLLATE Latin1_General_100_BIN2,\n subjectDigest varchar(71),scope nvarchar(100),producerDigest varchar(71),digest varchar(71),content nvarchar(max));\nDECLARE @producers TABLE(digest varchar(71) COLLATE Latin1_General_100_BIN2,content nvarchar(max),valid bit);\nINSERT @producers SELECT digest,content,CASE WHEN ISJSON(content)=1 AND DATALENGTH(digest)=71\n AND digest=N''sha256:''+LOWER(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),CONVERT(varchar(max),content COLLATE Latin1_General_100_BIN2_UTF8))),2))\n AND NULLIF(JSON_VALUE(CASE WHEN ISJSON(content)=1 THEN content ELSE N''{}'' END,''$.producerId''),N'''') IS NOT NULL\n AND NULLIF(JSON_VALUE(CASE WHEN ISJSON(content)=1 THEN content ELSE N''{}'' END,''$.manifestVersion''),N'''') IS NOT NULL\n AND NULLIF(JSON_VALUE(CASE WHEN ISJSON(content)=1 THEN content ELSE N''{}'' END,''$.provenance''),N'''') IS NOT NULL THEN 1 ELSE 0 END\nFROM OPENJSON(@p,''$.producers'') WITH(digest varchar(71),content nvarchar(max));\n\n-- Reject duplicate object keys in every embedded JSON document. Parsing must\n-- not give the kernel, SQL and host different interpretations of the same bytes.\nDECLARE @json TABLE(id int IDENTITY PRIMARY KEY,body nvarchar(max));\nINSERT @json(body) SELECT @p UNION ALL SELECT @manifest UNION ALL SELECT @claimText\n UNION ALL SELECT content FROM @parts WHERE ISJSON(content)=1\n UNION ALL SELECT content FROM @producers WHERE ISJSON(content)=1;\nDECLARE @at int=1,@end int=(SELECT MAX(id) FROM @json),@j nvarchar(max),@duplicate bit=0;\nWHILE @at<=@end\nBEGIN\n SELECT @j=body FROM @json WHERE id=@at;\n IF LEFT(LTRIM(@j),1)=N''{'' AND EXISTS(SELECT [key] COLLATE Latin1_General_100_BIN2 FROM OPENJSON(@j) GROUP BY [key] COLLATE Latin1_General_100_BIN2 HAVING COUNT(*)>1) SET @duplicate=1;\n INSERT @json(body) SELECT value FROM OPENJSON(@j) WHERE type IN(4,5);\n SET @at+=1; SET @end=(SELECT MAX(id) FROM @json);\n IF @end>100000 THROW 51000,''TRUST_INPUT_BOUND'',1;\nEND;\n\nDECLARE @sd varchar(71)=JSON_VALUE(@subject,''$.digest''),@scope nvarchar(100)=JSON_VALUE(@claim,''$.scope''),\n @run nvarchar(128)=JSON_VALUE(@manifest,''$.runId''),@terminal nvarchar(max),@admission nvarchar(max);\nSELECT @terminal=content FROM @parts WHERE role=''terminal'' AND class=''observation'' AND polarity=''SUPPORTS'' AND scope=@scope AND valid=1;\nSELECT @admission=content FROM @parts WHERE role=''admission'' AND class=''identity'' AND polarity=''SUPPORTS'' AND scope=@scope AND valid=1;\nINSERT @checks VALUES(''subject-manifest-digest-matches'',\n CASE WHEN @sd IS NULL OR @manifest=N''{}'' THEN ''NOT_OBSERVABLE''\n WHEN @duplicate=1 OR DATALENGTH(@sd)<>71 OR @sd<>N''sha256:''+LOWER(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),CONVERT(varchar(max),@manifest COLLATE Latin1_General_100_BIN2_UTF8))),2)) COLLATE Latin1_General_100_BIN2 THEN ''VIOLATED''\n WHEN EXISTS(SELECT 1 FROM OPENJSON(@manifest) m WHERE m.[key] LIKE ''%Digest'' AND (LEN(m.value)<>71 OR LEFT(m.value,7)<>N''sha256:'' OR SUBSTRING(m.value,8,64) COLLATE Latin1_General_100_BIN2 LIKE ''%[^0-9a-f]%'')) THEN ''VIOLATED''\n WHEN NOT EXISTS(SELECT 1 FROM OPENJSON(@policy,''$.identity.requiredRunFields'')) OR EXISTS(SELECT 1 FROM OPENJSON(@policy,''$.identity.requiredRunFields'') f WHERE NOT EXISTS(SELECT 1 FROM OPENJSON(@manifest) m WHERE m.[key]=f.value COLLATE Latin1_General_100_BIN2 AND m.type IN(1,5) AND NULLIF(m.value,N'''') IS NOT NULL)) THEN ''NOT_OBSERVABLE''\n ELSE ''SATISFIED'' END,N''Exact retained subject bytes and every declared identity field are required.'');\nINSERT @checks VALUES(''statement-matches-manifest'',\n CASE WHEN @claimText=N''{}'' OR JSON_VALUE(@claim,''$.statementDigest'') IS NULL THEN ''NOT_OBSERVABLE''\n WHEN JSON_VALUE(@claim,''$.statementDigest'')<>N''sha256:''+LOWER(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),CONVERT(varchar(max),@claimText COLLATE Latin1_General_100_BIN2_UTF8))),2)) COLLATE Latin1_General_100_BIN2 THEN ''VIOLATED''\n WHEN EXISTS(SELECT 1 FROM OPENJSON(@policy,''$.claimKinds'') k CROSS APPLY OPENJSON(k.value,''$.statementFields'') f\n WHERE JSON_VALUE(k.value,''$.id'')=JSON_VALUE(@claim,''$.kind'') AND NOT EXISTS(SELECT 1 FROM OPENJSON(@claimText) s WHERE s.[key]=f.value COLLATE Latin1_General_100_BIN2 AND s.type=1 AND NULLIF(s.value,N'''') IS NOT NULL)) THEN ''NOT_OBSERVABLE''\n WHEN EXISTS(SELECT 1 FROM OPENJSON(@claimText) s JOIN OPENJSON(@manifest) m ON s.[key]=m.[key] COLLATE Latin1_General_100_BIN2\n WHERE s.value<>m.value COLLATE Latin1_General_100_BIN2 OR DATALENGTH(s.value)<>DATALENGTH(m.value)) THEN ''VIOLATED''\n ELSE ''SATISFIED'' END,N''Claim identity fields and returned variant must be explicit and match the subject.'');\nINSERT @checks VALUES(''executor-attributable-to-run'',\n CASE WHEN @admission IS NULL OR @manifest=N''{}'' THEN ''NOT_OBSERVABLE''\n WHEN (SELECT COUNT(*) FROM @parts WHERE role=''admission'' AND class=''identity'' AND polarity=''SUPPORTS'' AND scope=@scope)<>1 THEN ''VIOLATED''\n WHEN EXISTS(SELECT 1 FROM (VALUES(''runId''),(''executorDigest''),(''executorProvenance''),(''capabilityDefinitionDigest''),(''graphDigest'')) f(id)\n WHERE NOT EXISTS(SELECT 1 FROM OPENJSON(@admission) a JOIN OPENJSON(@manifest) m ON a.[key]=m.[key] COLLATE Latin1_General_100_BIN2\n WHERE a.[key]=f.id AND a.value=m.value COLLATE Latin1_General_100_BIN2 AND DATALENGTH(a.value)=DATALENGTH(m.value))) THEN ''VIOLATED''\n ELSE ''SATISFIED'' END,N''An authenticated producer admission receipt must bind this exact run to its executor, definition and graph.'');\nINSERT @checks VALUES(''authority-selected-and-digest-matched'',\n CASE WHEN @policyBytes IS NULL OR @rule IS NULL OR JSON_VALUE(@rule,''$.available'')=''false''\n OR JSON_VALUE(@rule,''$.claimKind'')<>JSON_VALUE(@claim,''$.kind'') COLLATE Latin1_General_100_BIN2\n OR ISNULL(JSON_VALUE(@rule,''$.evaluation''),'''')<>''declared-evidence-prerequisites.v1''\n OR ISNULL(JSON_VALUE(@claim,''$.kind''),'''')<>''C1''\n OR JSON_VALUE(@rule,''$.scope'')<>@scope COLLATE Latin1_General_100_BIN2\n OR ISNULL(JSON_VALUE(@p,''$.target''),N'''')<>ISNULL(JSON_VALUE(@rule,''$.target''),N''?'') COLLATE Latin1_General_100_BIN2 THEN ''NOT_OBSERVABLE''\n WHEN NOT EXISTS(SELECT 1 FROM @parts WHERE class=''authority'' AND role=''policy'' AND polarity=''SUPPORTS'' AND scope=@scope AND digest=@policyDigest AND valid=1 AND DATALENGTH(content)=DATALENGTH(@policyBytes)) THEN ''NOT_OBSERVABLE''\n ELSE ''SATISFIED'' END,N''Only the pinned estate rule and exact scope\/target are evaluable; no inferred higher state.'');\nINSERT @checks VALUES(''observation-producer-identified'',\n CASE WHEN NOT EXISTS(SELECT 1 FROM @parts WHERE class=''observation'' AND polarity=''SUPPORTS'' AND scope=@scope) THEN ''NOT_OBSERVABLE''\n WHEN EXISTS(SELECT 1 FROM @parts e WHERE NOT EXISTS(SELECT 1 FROM @producers p WHERE p.digest=e.producerDigest AND p.valid=1))\n OR EXISTS(SELECT digest FROM @producers GROUP BY digest HAVING COUNT(*)<>1) THEN ''NOT_OBSERVABLE''\n ELSE ''SATISFIED'' END,N''Every evidence producer needs a retained identity; the ledger service must authenticate its source before persistence.'');\nINSERT @checks VALUES(''terminal-receipt-matches-statement'',\n CASE WHEN @terminal IS NULL THEN ''NOT_OBSERVABLE''\n WHEN (SELECT COUNT(*) FROM @parts WHERE role=''terminal'' AND class=''observation'' AND polarity=''SUPPORTS'' AND scope=@scope)<>1 THEN ''VIOLATED''\n WHEN ISNULL(JSON_VALUE(@terminal,''$.state''),N'''') NOT IN(''completed'',''failed'',''cancelled'',''timed-out'',''timed_out'')\n OR EXISTS(SELECT 1 FROM OPENJSON(@claimText) s WHERE NOT EXISTS(SELECT 1 FROM OPENJSON(@terminal) t\n WHERE t.[key]=s.[key] COLLATE Latin1_General_100_BIN2 AND t.value=s.value COLLATE Latin1_General_100_BIN2 AND DATALENGTH(t.value)=DATALENGTH(s.value))) THEN ''VIOLATED''\n ELSE ''SATISFIED'' END,N''One retained terminal receipt must explicitly report the exact statement.'');\nDECLARE @events TABLE([cursor] bigint,eventId nvarchar(256));\nINSERT @events SELECT TRY_CONVERT(bigint,JSON_VALUE(j.value,''$.cursor'')),JSON_VALUE(j.value,''$.eventId'')\nFROM @parts e CROSS APPLY OPENJSON(CASE WHEN ISJSON(e.content)=1 AND LEFT(LTRIM(e.content),1)=N''['' THEN e.content ELSE N''[]'' END) j\nWHERE e.role=''trace'' AND e.class=''observation'' AND e.polarity=''SUPPORTS'' AND e.scope=@scope AND e.valid=1 AND j.type=5;\nDECLARE @latest bigint=TRY_CONVERT(bigint,JSON_VALUE(@terminal,''$.latestCursor''));\nINSERT @checks VALUES(''trace-ranges-complete'',\n CASE WHEN @run IS NULL OR @latest IS NULL OR @latest<1 OR NOT EXISTS(SELECT 1 FROM @events) THEN ''NOT_OBSERVABLE''\n WHEN (SELECT COUNT_BIG(*) FROM @events)<>@latest OR (SELECT MIN([cursor]) FROM @events)<>1 OR (SELECT MAX([cursor]) FROM @events)<>@latest\n OR EXISTS(SELECT [cursor] FROM @events GROUP BY [cursor] HAVING COUNT(*)<>1)\n OR EXISTS(SELECT 1 FROM @events WHERE [cursor] IS NULL OR eventId IS NULL OR eventId<>CONCAT(N''urn:sda-api:run-event:'',@run,N'':'',[cursor]) COLLATE Latin1_General_100_BIN2)\n THEN ''VIOLATED'' ELSE ''SATISFIED'' END,N''All retained event cursors must be contiguous, unique and bound to this run.'');\nINSERT @checks VALUES(''retained-content-digests-match'',\n CASE WHEN @sd IS NULL OR @policyBytes IS NULL OR EXISTS(SELECT 1 FROM @parts WHERE content IS NULL) THEN ''NOT_OBSERVABLE''\n WHEN @invalidShape=1 OR @duplicate=1 OR EXISTS(SELECT 1 FROM @parts WHERE valid=0 OR id IS NULL OR NULLIF(id,N'''') IS NULL OR subjectDigest IS NULL OR subjectDigest<>@sd COLLATE Latin1_General_100_BIN2\n OR polarity IS NULL OR polarity NOT IN(''SUPPORTS'',''REFUTES'',''NOT_OBSERVABLE'')\n OR NOT EXISTS(SELECT 1 FROM OPENJSON(@policy,''$.evidenceClasses'') c WHERE c.value=class COLLATE Latin1_General_100_BIN2))\n OR EXISTS(SELECT id FROM @parts GROUP BY id HAVING COUNT(*)<>1) THEN ''VIOLATED''\n WHEN EXISTS(SELECT 1 FROM OPENJSON(@rule,''$.requiredEvidenceClasses'') c WHERE NOT EXISTS(SELECT 1 FROM @parts e WHERE e.class=c.value COLLATE Latin1_General_100_BIN2 AND e.polarity=''SUPPORTS'' AND e.scope=@scope AND e.valid=1)) THEN ''NOT_OBSERVABLE''\n WHEN NOT EXISTS(SELECT 1 FROM @parts WHERE role=''subject'' AND class=''identity'' AND polarity=''SUPPORTS'' AND scope=@scope AND digest=@sd AND valid=1)\n OR NOT EXISTS(SELECT 1 FROM @parts WHERE role=''statement'' AND class=''declaration'' AND polarity=''SUPPORTS'' AND scope=@scope AND digest=JSON_VALUE(@claim,''$.statementDigest'') AND valid=1) THEN ''NOT_OBSERVABLE''\n ELSE ''SATISFIED'' END,N''Content bytes, subject binding and all evidence classes are required. A digest alone cannot replay evidence.'');\nDECLARE @expected TABLE(id nvarchar(400) COLLATE Latin1_General_100_BIN2,digest varchar(71) COLLATE Latin1_General_100_BIN2);\nINSERT @expected VALUES(N''subject'',@sd),(N''statement'',JSON_VALUE(@claim,''$.statementDigest'')),(N''policy'',@policyDigest),(N''evaluator'',@evaluatorDigest);\nINSERT @expected SELECT N''evidence\/''+id,digest FROM @parts;\nINSERT @expected SELECT N''producer\/''+digest,digest FROM @producers;\nDECLARE @given TABLE(id nvarchar(400) COLLATE Latin1_General_100_BIN2,digest varchar(71) COLLATE Latin1_General_100_BIN2);\nINSERT @given SELECT id,digest FROM OPENJSON(@p,''$.inputManifest'') WITH(id nvarchar(400),digest varchar(71));\nINSERT @checks VALUES(''input-manifest-complete'',\n CASE WHEN EXISTS(SELECT id,digest FROM @expected EXCEPT SELECT id,digest FROM @given)\n OR EXISTS(SELECT id,digest FROM @given EXCEPT SELECT id,digest FROM @expected)\n OR EXISTS(SELECT id FROM @given GROUP BY id HAVING COUNT(*)<>1) OR NOT EXISTS(SELECT 1 FROM @given) THEN ''NOT_OBSERVABLE''\n ELSE ''SATISFIED'' END,N''The complete decision input manifest must retain every evidence, producer, policy and evaluator digest.'');\nINSERT @checks VALUES(''evaluator-identified-and-authorized'',\n CASE WHEN @evaluatorBytes IS NULL OR @evaluatorDigest IS NULL OR ISNULL(JSON_VALUE(@p,''$.evaluatorDigest''),N'''')<>@evaluatorDigest COLLATE Latin1_General_100_BIN2 THEN ''NOT_OBSERVABLE''\n ELSE ''SATISFIED'' END,N''The caller must pin this installed declared evaluator; only an authorized ledger service may record its result.'');\n-- New policy checks cannot silently pass an older evaluator implementation.\nINSERT @checks SELECT value,''NOT_OBSERVABLE'',N''The installed evaluator does not implement this declared check.''\nFROM OPENJSON(@rule,''$.requiredChecks'') r WHERE NOT EXISTS(SELECT 1 FROM @checks c WHERE c.id=r.value COLLATE Latin1_General_100_BIN2);\nDECLARE @contradictions nvarchar(max)=(SELECT id,digest,producerDigest FROM @parts WHERE polarity=''REFUTES'' AND scope=@scope FOR JSON PATH);\nDECLARE @outcome varchar(20)=CASE\n WHEN EXISTS(SELECT 1 FROM @parts WHERE polarity=''REFUTES'' AND scope=@scope) OR EXISTS(SELECT 1 FROM @checks WHERE outcome=''VIOLATED'') THEN ''VIOLATED''\n WHEN NULLIF(@scope,N'''') IS NULL OR NULLIF(JSON_VALUE(@claim,''$.id''),N'''') IS NULL OR @rule IS NULL OR EXISTS(SELECT 1 FROM @checks WHERE outcome<>''SATISFIED'')\n OR EXISTS(SELECT 1 FROM @parts WHERE polarity=''NOT_OBSERVABLE'' AND scope=@scope) THEN ''NOT_OBSERVABLE''\n ELSE ''SATISFIED'' END;\nSELECT (SELECT N''run-evidence-claim-evaluation.v1'' AS contractId,\n JSON_VALUE(@claim,''$.id'') AS claimId,JSON_VALUE(@claim,''$.kind'') AS claimKind,@scope AS scope,@sd AS subjectDigest,\n JSON_VALUE(@p,''$.ruleId'') AS ruleId,@ruleDigest AS ruleDigest,@policyDigest AS policyDigest,\n @evaluatorDigest AS evaluatorDigest,@outcome AS outcome,\n CASE WHEN @outcome=''SATISFIED'' THEN JSON_VALUE(@rule,''$.target'') END AS eligibleState,\n N''sha256:''+LOWER(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),CONVERT(varchar(max),@p COLLATE Latin1_General_100_BIN2_UTF8))),2)) AS inputsDigest,\n JSON_QUERY((SELECT id,outcome,reason FROM @checks ORDER BY id FOR JSON PATH)) AS checks,\n JSON_QUERY(COALESCE(@contradictions,N''[]'')) AS contradictions,\n JSON_QUERY(COALESCE(JSON_QUERY(@rule,''$.limitations''),N''[]'')) AS limitations,\n JSON_QUERY(COALESCE((SELECT id AS reference,reason FROM @checks WHERE outcome<>''SATISFIED'' ORDER BY id FOR JSON PATH),N''[]'')) AS missingOrInvalid,\n JSON_QUERY(COALESCE((SELECT id AS reference,digest FROM @parts WHERE content IS NULL FOR JSON PATH),N''[]'')) AS unavailableContent,\n JSON_QUERY(@policy,''$.invalidation'') AS invalidation,\n N''Evaluation of a retained ledger snapshot; caller authentication and append-only persistence are enforced by the ledger service. No claim or disposition is written by this reading.'' AS boundary\n FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) AS value;","resultColumn":"value"}}]}]}';
DECLARE @pd binary(32)=0x98b97712ba40153553186212b6094970433b9b4fee810fb67e2c9921368f4454,@ed binary(32)=0x0d8869aafd2ae49894f26b76b1d8bf2ea347289b355fd8d0009f13cb106e25a1;
DECLARE @pb varbinary(max)=CONVERT(varbinary(max),CONVERT(varchar(max),@policy COLLATE Latin1_General_100_BIN2_UTF8)),
 @eb varbinary(max)=CONVERT(varbinary(max),CONVERT(varchar(max),@evaluator COLLATE Latin1_General_100_BIN2_UTF8));
IF HASHBYTES('SHA2_256',@pb)<>@pd OR HASHBYTES('SHA2_256',@eb)<>@ed THROW 51000,'LEDGER_AUTHORITY_DRIFT',1;
IF JSON_VALUE(@policy,'$.address.id')<>N'run-evidence-trust-policy.v1'
 OR JSON_VALUE(@evaluator,'$.capabilityId')<>N'evaluate-run-evidence-claim' THROW 51000,'LEDGER_AUTHORITY_IDENTITY',1;
DECLARE @authorities TABLE(digest binary(32),address nvarchar(512),kind varchar(32),bytes varbinary(max));
INSERT @authorities VALUES(@pd,N'sidefx:authorities/run-evidence-trust-policy.v1','policy',@pb),
 (@ed,N'sidefx:capability-documents/evaluate-run-evidence-claim','evaluator',@eb);
IF EXISTS(SELECT 1 FROM @authorities a JOIN ledger.authority_ref r ON r.definition_digest=a.digest
 WHERE r.content<>a.bytes OR r.authority_kind<>a.kind OR r.semantic_address<>a.address COLLATE Latin1_General_100_BIN2)
 THROW 51000,'LEDGER_AUTHORITY_CONFLICT',1;
INSERT ledger.authority_ref SELECT digest,address,kind,bytes,SYSUTCDATETIME() FROM @authorities a
 WHERE NOT EXISTS(SELECT 1 FROM ledger.authority_ref r WHERE r.definition_digest=a.digest);
INSERT ledger.trust_state SELECT @pd,id,name FROM OPENJSON(@policy,'$.semantics.states') WITH(id int,name varchar(64)) v
 WHERE NOT EXISTS(SELECT 1 FROM ledger.trust_state r WHERE r.policy_digest=@pd AND r.state_id=v.id);
INSERT ledger.evidence_class SELECT @pd,value FROM OPENJSON(@policy,'$.semantics.evidenceClasses') v
 WHERE NOT EXISTS(SELECT 1 FROM ledger.evidence_class r WHERE r.policy_digest=@pd AND r.class_name=v.value COLLATE Latin1_General_100_BIN2);
INSERT ledger.claim_kind SELECT @pd,JSON_VALUE(value,'$.id'),value FROM OPENJSON(@policy,'$.semantics.claimKinds') v
 WHERE NOT EXISTS(SELECT 1 FROM ledger.claim_kind r WHERE r.policy_digest=@pd AND r.kind_id=JSON_VALUE(v.value,'$.id') COLLATE Latin1_General_100_BIN2);
INSERT ledger.evaluation_rule SELECT @pd,JSON_VALUE(value,'$.id'),JSON_VALUE(value,'$.claimKind'),JSON_VALUE(value,'$.scope'),JSON_VALUE(value,'$.target'),
 CASE WHEN JSON_VALUE(value,'$.available')='false' THEN 0 ELSE 1 END,
 HASHBYTES('SHA2_256',CONVERT(varbinary(max),CONVERT(varchar(max),value COLLATE Latin1_General_100_BIN2_UTF8))),value
 FROM OPENJSON(@policy,'$.semantics.rules') v WHERE NOT EXISTS(SELECT 1 FROM ledger.evaluation_rule r WHERE r.policy_digest=@pd AND r.rule_id=JSON_VALUE(v.value,'$.id') COLLATE Latin1_General_100_BIN2);
-- Bidirectional comparisons detect extra rows and altered reference copies.
IF EXISTS(SELECT state_id,state_name FROM ledger.trust_state WHERE policy_digest=@pd
 EXCEPT SELECT id,name COLLATE Latin1_General_100_BIN2 FROM OPENJSON(@policy,'$.semantics.states') WITH(id int,name varchar(64)))
 OR (SELECT COUNT(*) FROM ledger.trust_state WHERE policy_digest=@pd)<>(SELECT COUNT(*) FROM OPENJSON(@policy,'$.semantics.states'))
 OR EXISTS(SELECT class_name FROM ledger.evidence_class WHERE policy_digest=@pd EXCEPT SELECT value COLLATE Latin1_General_100_BIN2 FROM OPENJSON(@policy,'$.semantics.evidenceClasses'))
 OR (SELECT COUNT(*) FROM ledger.evidence_class WHERE policy_digest=@pd)<>(SELECT COUNT(*) FROM OPENJSON(@policy,'$.semantics.evidenceClasses'))
 OR EXISTS(SELECT kind_id,kind_json FROM ledger.claim_kind WHERE policy_digest=@pd EXCEPT SELECT JSON_VALUE(value,'$.id') COLLATE Latin1_General_100_BIN2,value FROM OPENJSON(@policy,'$.semantics.claimKinds'))
 OR (SELECT COUNT(*) FROM ledger.claim_kind WHERE policy_digest=@pd)<>(SELECT COUNT(*) FROM OPENJSON(@policy,'$.semantics.claimKinds'))
 OR EXISTS(SELECT rule_id,rule_json FROM ledger.evaluation_rule WHERE policy_digest=@pd EXCEPT SELECT JSON_VALUE(value,'$.id') COLLATE Latin1_General_100_BIN2,value FROM OPENJSON(@policy,'$.semantics.rules'))
 OR (SELECT COUNT(*) FROM ledger.evaluation_rule WHERE policy_digest=@pd)<>(SELECT COUNT(*) FROM OPENJSON(@policy,'$.semantics.rules'))
 THROW 51000,'LEDGER_VOCABULARY_DRIFT',1;
EXEC(N'CREATE OR ALTER PROCEDURE [ledger].[read_evaluation_authority]
 @policy_digest varbinary(32),@evaluator_digest varbinary(32)
AS
BEGIN
 SET NOCOUNT ON;
 IF DATALENGTH(@policy_digest)<>32 OR DATALENGTH(@evaluator_digest)<>32
 OR @policy_digest IS NULL OR @evaluator_digest IS NULL THROW 51000,''LEDGER_AUTHORITY_PIN_REQUIRED'',1;
 SELECT p.definition_digest AS policy_digest,p.content AS policy_content,
 e.definition_digest AS evaluator_digest,e.content AS evaluator_content
 FROM ledger.authority_ref p CROSS JOIN ledger.authority_ref e
 WHERE p.definition_digest=@policy_digest AND p.authority_kind=''policy''
 AND e.definition_digest=@evaluator_digest AND e.authority_kind=''evaluator'';
END');
EXEC(N'CREATE OR ALTER PROCEDURE [ledger].[read_evaluation_rules]
 @policy_digest varbinary(32)
AS
BEGIN
 SET NOCOUNT ON;
 IF DATALENGTH(@policy_digest)<>32 OR @policy_digest IS NULL THROW 51000,''LEDGER_AUTHORITY_PIN_REQUIRED'',1;
 SELECT rule_id,claim_kind,scope,target_state,available,rule_digest,rule_json
 FROM ledger.evaluation_rule WHERE policy_digest=@policy_digest ORDER BY rule_id;
END');
IF DATABASE_PRINCIPAL_ID(N'sfx_ledger_runtime') IS NULL CREATE ROLE sfx_ledger_runtime;
DENY SELECT,INSERT,UPDATE,DELETE ON SCHEMA::ledger TO sfx_ledger_runtime;
GRANT EXECUTE ON ledger.read_evaluation_authority TO sfx_ledger_runtime;
GRANT EXECUTE ON ledger.read_evaluation_rules TO sfx_ledger_runtime;
SELECT N'trust-authority-reference' AS check_name,LOWER(CONVERT(varchar(64),@pd,2)) AS policy_digest,
 LOWER(CONVERT(varchar(64),@ed,2)) AS evaluator_digest,
 (SELECT COUNT(*) FROM ledger.trust_state WHERE policy_digest=@pd) AS states,
 (SELECT COUNT(*) FROM ledger.evidence_class WHERE policy_digest=@pd) AS evidence_classes,
 (SELECT COUNT(*) FROM ledger.claim_kind WHERE policy_digest=@pd) AS claim_kinds,
 (SELECT COUNT(*) FROM ledger.evaluation_rule WHERE policy_digest=@pd) AS rules;
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
